<script lang="ts" module>import type { Snippet } from 'svelte'; import type { RxColor } from '$lib/registry/lib/color'; export interface TabsProps { value?:string; orientation?:'horizontal'|'vertical'; activationMode?:'automatic'|'manual'; color?:RxColor; variant?:'default'|'bubble'|'card'|'chrome'|'gooey'|'neon'; onValueChange?:(value:string)=>void; children:Snippet; }</script>
